#!/usr/bin/env bash
# Per-user-turn routing re-inject (bd tea-rags-mcp-nknkg.2). Benchmarks showed
# tea-rags use collapsing after ~14 questions of one session; restating the
# core routing essentials at every user turn keeps them current.
#
# One script, three harnesses (`--harness claude|codex|cursor`; Codex and Cursor
# ship this file byte-identical, generated by scripts/gen-harness-*.ts):
#   claude, codex — UserPromptSubmit → hookSpecificOutput.additionalContext.
#   cursor        — beforeSubmitPrompt has no context channel (output is only
#                   `continue` / `user_message`), so it arms the turn and answers
#                   {"continue":true}; the turn's first postToolUse delivers the
#                   lines as `additional_context`. A turn with no tool call gets
#                   nothing — the documented gap.
#
# Single source of the lines: the fenced block under "## The block to inject" in
# rules/references/turn-routing.md. Codex and Cursor get it pre-rendered in their
# dialect as scripts/turn-routing.txt next to this script.
#
# Fails open: no jq, no text, unparsable input, unwritable state — the prompt
# and the tool proceed (Cursor: always a schema-valid JSON answer). Exit 0.

HARNESS=claude
while [ $# -gt 0 ]; do
  case "$1" in
    --harness) HARNESS="${2:-claude}"; shift 2 || shift ;;
    *) shift ;;
  esac
done

EMPTY=""
[ "$HARNESS" = cursor ] && EMPTY='{}'
done_with() { [ -z "$1" ] || echo "$1"; exit 0; }

INPUT=$(cat)
command -v jq >/dev/null 2>&1 || {
  case "$INPUT" in *beforeSubmitPrompt*) done_with '{"continue":true}' ;; esac
  done_with "$EMPTY"
}
EVENT=$(printf '%s' "$INPUT" | jq -r '.hook_event_name // empty' 2>/dev/null)
[ "$EVENT" = beforeSubmitPrompt ] && EMPTY='{"continue":true}'

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
if [ -f "$SCRIPT_DIR/turn-routing.txt" ]; then
  BLOCK=$(cat "$SCRIPT_DIR/turn-routing.txt" 2>/dev/null)
else
  BLOCK=$(awk '
    /^## The block to inject/ { section = 1; next }
    section && /^```/ { if (inside) exit; inside = 1; next }
    inside { print }
  ' "$SCRIPT_DIR/../rules/references/turn-routing.md" 2>/dev/null)
fi
[ -n "$BLOCK" ] || done_with "$EMPTY"

case "$EVENT" in
  UserPromptSubmit)
    jq -n --arg context "$BLOCK" '{
      hookSpecificOutput: { hookEventName: "UserPromptSubmit", additionalContext: $context }
    }' 2>/dev/null
    exit 0
    ;;
  beforeSubmitPrompt | postToolUse) ;;
  *) done_with "$EMPTY" ;;
esac

# Cursor: one pending marker per conversation, armed by the prompt, spent by the
# turn's first tool result.
SID=$(printf '%s' "$INPUT" | jq -r '.conversation_id // .session_id // empty' 2>/dev/null | tr -c 'A-Za-z0-9_.-' '_')
[ -n "$SID" ] || done_with "$EMPTY"
STATE_DIR="${TEA_RAGS_HOOK_STATE_DIR:-${PLUGIN_DATA:-${TMPDIR:-/tmp}}/tea-rags-hooks}"
MARK="$STATE_DIR/turn-$HARNESS-$SID"
if [ "$EVENT" = beforeSubmitPrompt ]; then
  mkdir -p "$STATE_DIR" 2>/dev/null && : > "$MARK" 2>/dev/null
  done_with '{"continue":true}'
fi
[ -f "$MARK" ] || done_with "$EMPTY"
rm -f "$MARK" 2>/dev/null
jq -n --arg context "$BLOCK" '{ additional_context: $context }' 2>/dev/null || echo '{}'
exit 0
